CREATE TABLE "api_calls" (
	"day" text NOT NULL,
	"role" text NOT NULL,
	"service" text NOT NULL,
	"calls" integer DEFAULT 0 NOT NULL,
	"throttled" integer DEFAULT 0 NOT NULL,
	CONSTRAINT "api_calls_day_role_service_pk" PRIMARY KEY("day","role","service")
);
