CREATE INDEX "sign_in_attempts_ip" ON "sign_in_attempts" USING btree ("ip","at");
--> statement-breakpoint
-- the counts kept so far in meta (api-calls:<role>, one JSON per process) carry over; AniList's rate answer refreshes on its next call
INSERT INTO "api_calls" ("day", "role", "service", "calls", "throttled")
SELECT m.v->>'day', substr(m.k, 11), s.key, s.value::int, coalesce((m.v->'throttled'->>s.key)::int, 0)
FROM "meta" m, jsonb_each_text(m.v->'n') s WHERE m.k LIKE 'api-calls:%' AND m.v ? 'day';
--> statement-breakpoint
DELETE FROM "meta" WHERE "k" LIKE 'api-calls:%';
